"use strict";
import { useCallback, useState, useEffect } from "react";
import { useIncentiveContract } from "./useIncentiveContract";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
export function useIncentiveFlow({ selectedPool, incentiveToken, incentiveAmount, onSuccess }) {
  const {
    approveToken,
    createIncentive,
    createIncentiveBatched,
    needsApproval,
    isWritePending,
    isConfirming,
    isSuccess,
    writeError,
    transactionHash,
    refetchAllowance,
    supportsEip5792
  } = useIncentiveContract({ selectedPool, incentiveToken, incentiveAmount });
  const [flowState, setFlowState] = useState({
    step: "input"
  });
  const [batchId, setBatchId] = useState(null);
  const [lastTransactionStep, setLastTransactionStep] = useState(null);
  const resetFlow = useCallback(() => {
    setFlowState({ step: "input" });
    setLastTransactionStep(null);
    setBatchId(null);
  }, []);
  const handleSuccess = useCallback(async () => {
    if (!incentiveAmount || !incentiveToken || !selectedPool) return;
    setFlowState({
      step: "success",
      transactionHash: transactionHash || batchId || void 0
    });
    const poolName = selectedPool?.symbol || "pool";
    const amount = incentiveAmount.toSignificant(6);
    const token = incentiveToken.symbol || "tokens";
    popupRegistry.addPopup({
      type: PopupType.IncentiveSuccess,
      content: {
        type: "success",
        title: "Incentive Deposited",
        description: `Successfully deposited ${amount} ${token} as incentive for ${poolName}`,
        hash: transactionHash || batchId,
        action: "deposit"
      }
    }, `incentive-deposit-success-${transactionHash || batchId}`, 8e3);
    onSuccess?.();
    setTimeout(() => {
      resetFlow();
    }, 2e3);
  }, [transactionHash, batchId, incentiveAmount, incentiveToken, selectedPool, onSuccess, resetFlow]);
  const executeApproval = useCallback(async () => {
    if (!incentiveAmount) return;
    setFlowState({ step: "approve" });
    setLastTransactionStep("approve");
    try {
      await approveToken(incentiveAmount);
    } catch (error) {
      console.error("Approval failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to approve token";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Token approval was cancelled by user",
            action: "deposit"
          }
        }, `incentive-approve-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Token Approval Failed",
            description: `Failed to approve token: ${errorMessage}`,
            action: "deposit"
          }
        }, `incentive-approve-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
    }
  }, [incentiveAmount, approveToken]);
  const executeCreateIncentive = useCallback(async () => {
    if (!incentiveAmount) return;
    setFlowState({ step: "create" });
    setLastTransactionStep("create");
    try {
      await createIncentive({ amount: incentiveAmount });
    } catch (error) {
      console.error("Create incentive failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to create incentive";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Incentive creation was cancelled by user",
            action: "deposit"
          }
        }, `incentive-create-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Incentive Creation Failed",
            description: `Failed to create incentive: ${errorMessage}`,
            action: "deposit"
          }
        }, `incentive-create-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
    }
  }, [incentiveAmount, createIncentive]);
  const executeBatchedIncentive = useCallback(async () => {
    if (!incentiveAmount) return;
    setFlowState({ step: "create" });
    setLastTransactionStep("create");
    try {
      const id = await createIncentiveBatched({ amount: incentiveAmount });
      setBatchId(id);
      setFlowState((current) => ({
        ...current,
        step: "confirming",
        transactionHash: id
      }));
      setTimeout(() => {
        handleSuccess();
      }, 3e3);
    } catch (error) {
      console.error("Batched incentive failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to create batched incentive";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Batched incentive creation was cancelled by user",
            action: "deposit"
          }
        }, `incentive-batched-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Batched Incentive Failed",
            description: `Failed to create batched incentive: ${errorMessage}`,
            action: "deposit"
          }
        }, `incentive-batched-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
      setBatchId(null);
    }
  }, [incentiveAmount, createIncentiveBatched, handleSuccess]);
  const executeFlow = useCallback(async () => {
    if (!incentiveAmount || !incentiveToken || !selectedPool) return;
    const approvalNeeded = needsApproval(incentiveAmount);
    if (supportsEip5792 && approvalNeeded) {
      await executeBatchedIncentive();
    } else if (approvalNeeded) {
      await executeApproval();
    } else {
      await executeCreateIncentive();
    }
  }, [incentiveAmount, incentiveToken, selectedPool, needsApproval, supportsEip5792, executeBatchedIncentive, executeApproval, executeCreateIncentive]);
  useEffect(() => {
    if (isConfirming) {
      setFlowState((current) => ({
        ...current,
        step: "confirming",
        transactionHash
      }));
    } else if (isSuccess && lastTransactionStep) {
      if (lastTransactionStep === "approve") {
        setLastTransactionStep(null);
        setTimeout(() => {
          refetchAllowance().then(() => {
            executeCreateIncentive();
          });
        }, 1e3);
      } else if (lastTransactionStep === "create") {
        setLastTransactionStep(null);
        handleSuccess();
      }
    } else if (writeError) {
      const errorMessage = writeError.message;
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Transaction was cancelled by user",
            action: "deposit"
          }
        }, `incentive-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.IncentiveError,
          content: {
            type: "error",
            title: "Transaction Failed",
            description: `Transaction failed: ${errorMessage}`,
            action: "deposit"
          }
        }, `incentive-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
    }
  }, [isConfirming, isSuccess, writeError, transactionHash, lastTransactionStep, handleSuccess, executeCreateIncentive, refetchAllowance]);
  return {
    // Flow state
    flowState,
    resetFlow,
    // Actions
    executeFlow,
    // Computed values
    needsApproval: incentiveAmount ? needsApproval(incentiveAmount) : false,
    // Loading states
    isProcessing: isWritePending || isConfirming,
    // Batching support
    supportsEip5792,
    batchId
  };
}
