"use strict";
import { Percent, Token } from "@uniswap/sdk-core";
import { LiquidityPositionInfoBadges } from "components/Liquidity/LiquidityPositionInfoBadges";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import CurrencyLogo from "components/Logo/CurrencyLogo";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { formatPoolDisplayName, getPoolTypeDisplay } from "hooks/useAbstractLiquidityPools";
import { useUserGaugeDeposits } from "hooks/useUserGaugeDeposits";
import { useUserIncentiveDeposits } from "hooks/useUserIncentiveDeposits";
import { useChainIncentiveData, calculatePoolIncentivesFromChain } from "hooks/useChainIncentiveData";
import { useMemo } from "react";
import { DollarSign, TrendingUp, Gift } from "react-feather";
import { Button } from "tamagui";
import { Flex, Separator, Text, useSporeColors } from "ui/src";
import { GoldenVerified, InfoCircleFilled, Plus } from "ui/src/components/icons";
import { useFormatter } from "utils/formatNumbers";
import { useChainId } from "wagmi";
import JSBI from "jsbi";
import { useIncentivizeContext } from "../ContextProvider";
export default function SinglePool({ pool, gaugeApr }) {
  const { setIncentivizeStep, setSelectedPool } = useIncentivizeContext();
  const colors = useSporeColors();
  const formatter = useFormatter();
  const chainId = useChainId();
  const { getDepositsByPool, hasDepositsInPool } = useUserGaugeDeposits();
  const {
    getTotalDepositedInPool: getTotalIncentiveDeposits,
    getDepositSummaryForPool: getIncentiveSummary,
    getDepositTokensForPool,
    hasDepositsInPool: hasIncentiveDeposits,
    isLoading: isLoadingIncentives
  } = useUserIncentiveDeposits();
  const gaugeData = pool.gauge ? [{ id: pool.gauge.id, bribeContract: pool.gauge.bribeContract }] : [];
  const { data: chainIncentiveData = [], isLoading: chainIncentiveLoading } = useChainIncentiveData(gaugeData);
  const currencies = useMemo(() => {
    if (!pool.token0 || !pool.token1) return [void 0, void 0];
    try {
      const token0 = new Token(
        chainId,
        pool.token0.id,
        parseInt(pool.token0.decimals),
        pool.token0.symbol,
        pool.token0.name
      );
      const token1 = new Token(
        chainId,
        pool.token1.id,
        parseInt(pool.token1.decimals),
        pool.token1.symbol,
        pool.token1.name
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for pool logos:", error);
      return [void 0, void 0];
    }
  }, [pool.token0, pool.token1, chainId]);
  const poolName = pool.token0?.symbol && pool.token1?.symbol ? `${pool.token0.symbol}/${pool.token1.symbol}` : formatPoolDisplayName(pool);
  const poolType = getPoolTypeDisplay(pool);
  const tvl = useMemo(() => {
    const candidates = [pool.gauge?.totalValueLockedUSD, pool.totalValueLockedUSD, pool.reserveUSD];
    for (const candidate of candidates) {
      if (candidate === void 0 || candidate === null) continue;
      const numeric = typeof candidate === "number" ? candidate : Number.parseFloat(typeof candidate === "string" ? candidate : String(candidate));
      if (Number.isFinite(numeric) && numeric > 0) {
        return numeric;
      }
    }
    return void 0;
  }, [pool.gauge?.totalValueLockedUSD, pool.totalValueLockedUSD, pool.reserveUSD]);
  const incentiveAprDisplay = useMemo(() => {
    if (!gaugeApr || gaugeApr.aprPercent === void 0) {
      return "-";
    }
    const fraction = gaugeApr.aprPercent / 100;
    const numerator = Math.round(fraction * 1e6);
    const percentObj = new Percent(JSBI.BigInt(numerator), JSBI.BigInt(1e6));
    return formatter.formatPercent(percentObj, 2);
  }, [gaugeApr, formatter]);
  const userDeposits = getDepositsByPool(pool.id);
  const hasDeposits = hasDepositsInPool(pool.id);
  const totalStaked = userDeposits.reduce((sum, deposit) => sum + parseFloat(deposit.stakedAmount), 0);
  const totalUnstaked = userDeposits.reduce((sum, deposit) => sum + parseFloat(deposit.unstakedAmount), 0);
  const totalPendingRewards = userDeposits.reduce((sum, deposit) => sum + parseFloat(deposit.pendingRewards), 0);
  const userIncentiveDeposits = getTotalIncentiveDeposits(pool.id);
  const incentiveSummary = getIncentiveSummary(pool.id);
  const incentiveTokens = getDepositTokensForPool(pool.id);
  const poolIncentivesData = useMemo(() => {
    if (!pool.gauge?.id || chainIncentiveData.length === 0) {
      return { incentiveDetails: [], hasIncentives: false };
    }
    const result = calculatePoolIncentivesFromChain(chainIncentiveData, pool.gauge.id);
    return {
      incentiveDetails: result.incentiveDetails,
      hasIncentives: result.incentiveDetails.length > 0
    };
  }, [chainIncentiveData, pool.gauge?.id]);
  const allIncentiveTokenObjects = useMemo(() => {
    return poolIncentivesData.incentiveDetails.map(
      (detail) => new Token(
        chainId,
        detail.token,
        18,
        // Default decimals, actual decimals from chain data
        detail.symbol || "TOKEN",
        detail.symbol || "TOKEN"
      )
    );
  }, [poolIncentivesData.incentiveDetails, chainId]);
  const incentiveTokenObjects = useMemo(() => {
    return incentiveTokens.map(
      (token) => new Token(
        chainId,
        token.address,
        token.decimals,
        token.symbol,
        token.symbol
      )
    );
  }, [incentiveTokens, chainId]);
  const handlePoolSelect = () => {
    setSelectedPool(pool);
    setIncentivizeStep("step-2");
  };
  const poolAddress = pool.id || pool.pool;
  const gaugeAddress = pool.gauge?.id || pool.gauge?.gaugeAddress || pool.gaugeAddress;
  const protocolVersion = pool.protocol || pool.gauge?.poolType || "V2";
  const feeTier = pool.tickSpacing || pool.gauge?.tickSpacing;
  const getFeePercentage = () => {
    if (protocolVersion === "V2") {
      return "0.30";
    } else if (feeTier) {
      const tickSpacing = parseInt(feeTier);
      const TICK_SPACING_TO_FEE = {
        1: 100,
        // 0.01%
        50: 500,
        // 0.05%
        100: 500,
        // 0.05%
        200: 3e3,
        // 0.30%
        2e3: 1e4
        // 1.00%
      };
      const feeBasisPoints = TICK_SPACING_TO_FEE[tickSpacing] || 3e3;
      return (feeBasisPoints / 1e4).toFixed(2);
    }
    return "0.30";
  };
  const getPoolTypeDisplayText = () => {
    if (protocolVersion === "V2") {
      return "Basic Volatile";
    } else {
      return "Concentrated";
    }
  };
  const rowData = [
    {
      label: "APR",
      value: incentiveAprDisplay
    },
    {
      label: "TVL",
      value: tvl ? formatter.formatCompactNumber(tvl) : "-"
    }
  ];
  return <Flex
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
    p={"$padding12"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    hoverStyle={{
      borderColor: "$surface3Hovered",
      transform: "translateY(-1px)"
    }}
    group
    cursor="pointer"
    onPress={handlePoolSelect}
    transition="all 0.3s ease"
  >
      <Flex
    className="top"
    $platform-web={{ display: "grid", gridTemplateColumns: "3.5fr 1fr 1fr" }}
    $lg={{ gridTemplateColumns: "1fr" }}
  >
        <Flex className="left" row gap={"$gap12"} $lg={{ mb: "$spacing16" }}>
          <DoubleCurrencyLogo currencies={currencies} size={34} />

          <Flex flexDirection="column" justifyContent="center" gap={"$gap4"}>
            <Flex row gap={"$gap8"} alignItems="center">
              <Text variant="subheading2">{poolName}</Text>
              <GoldenVerified size="$icon.16" />
              <MouseoverTooltip
    text={<PoolAndGaugeAddress poolAddress={poolAddress} gaugeAddress={gaugeAddress} />}
    size={TooltipSize.Max}
    placement="top"
  >
                <Flex transition="opacity 0.3s ease" opacity={0} $md={{ opacity: 1 }} $group-hover={{ opacity: 1 }}>
                  <InfoCircleFilled size={"$icon.16"} color={"$neutral2"} />
                </Flex>
              </MouseoverTooltip>
            </Flex>
            <Flex row gap={"$gap4"} alignItems="center" mt={"$spacing4"}>
              <LiquidityPositionInfoBadges
    size="small"
    versionLabel={protocolVersion}
    feeTier={protocolVersion === "V3" ? (parseFloat(getFeePercentage()) * 1e4).toString() : void 0}
    poolType={protocolVersion === "V2" ? "volatile" : void 0}
  />
            </Flex>
          </Flex>
        </Flex>
        {rowData.map((item) => <Flex
    key={item.label}
    className="rebase"
    flexDirection="column"
    gap={"$gap12"}
    justifyContent="center"
    alignItems="flex-end"
    $lg={{
      flexDirection: "row",
      justifyContent: "space-between",
      alignItems: "center",
      py: "$spacing12",
      borderTopWidth: 1,
      borderTopColor: "$surface3",
      gap: 0
    }}
  >
            <Text variant="body3" color={"$neutral2"}>
              {item.label}
            </Text>
            <Text variant="body3" fontSize={"$mdall"}>
              {item.value}
            </Text>
          </Flex>)}
      </Flex>
      <Separator my={"$gap12"} width={"100%"} borderColor={"$surface3"} height={1} $lg={{ mt: "$gap8" }} />
      <Flex className="bottom" flexDirection="column" gap={"$gap12"}>
        {
    /* Show ALL pool incentives (from all users) */
  }
        <Flex row justifyContent="space-between" alignItems="center" gap={"$gap12"}>
          <Flex row gap={"$gap16"} alignItems="center" flex={1} flexWrap="wrap">
            {chainIncentiveLoading ? <Text variant="body4" color="$neutral2">
                Loading incentives...
              </Text> : poolIncentivesData.hasIncentives ? <Flex flexDirection="column" gap={"$gap8"} alignItems="flex-start">
                <Flex row alignItems="center" gap={"$gap8"}>
                  <Gift size={14} color={colors.accent1.val} />
                  <Text variant="body4" color="$neutral2">
                    Total incentives:
                  </Text>
                </Flex>
                {poolIncentivesData.incentiveDetails.map((detail, index) => <MouseoverTooltip
    key={detail.token}
    text={`Total ${detail.amount} ${detail.symbol} deposited as incentive for this pool by all users`}
    size={TooltipSize.Small}
  >
                    <Flex row alignItems="center" gap={"$gap4"}>
                      <Text variant="body4" color="$accent1" fontWeight="$medium">
                        {formatter.formatCompactNumber(detail.amount)} {detail.symbol}
                      </Text>
                      <CurrencyLogo currency={allIncentiveTokenObjects[index]} size={16} />
                    </Flex>
                  </MouseoverTooltip>)}
              </Flex> : <Text variant="body4" color="$neutral3">
                No incentives yet
              </Text>}
          </Flex>
          <Button
    py={"$padding16"}
    px={"$padding12"}
    borderRadius={"$rounded8"}
    transition="all 0.3s ease"
    backgroundColor={"transparent"}
    borderWidth={1}
    borderColor={"$surface3"}
    $group-hover={{ backgroundColor: "$accent2" }}
    hoverStyle={{ backgroundColor: "$accent2" }}
  >
            <Flex row gap={"$gap4"} alignItems="center">
              <Plus size={"$icon.12"} color={"$neutral2"} />
              <Text variant="buttonLabel4" color={"$neutral1"} fontWeight={"$medium"}>
                Add incentive
              </Text>
            </Flex>
          </Button>
        </Flex>

        {
    /* User's personal deposits section - shown on separate line */
  }
        {(hasIncentiveDeposits(pool.id) || hasDeposits) && <Flex row gap={"$gap16"} alignItems="center" flexWrap="wrap">
            {
    /* User's incentive deposits */
  }
            {hasIncentiveDeposits(pool.id) && incentiveTokens.length > 0 && <Flex row alignItems="center" gap={"$gap8"} flexWrap="wrap">
                <Text variant="body4" color="$neutral2" fontSize={"$micro"}>
                  Your incentives:
                </Text>
                {incentiveTokens.map((token, index) => <MouseoverTooltip
    key={token.address}
    text={`You have deposited ${token.amount} ${token.symbol} as incentive for this pool`}
    size={TooltipSize.Small}
  >
                    <Flex row alignItems="center" gap={"$gap4"}>
                      <Text variant="body4" color="$accent1" fontWeight="$medium" fontSize={"$micro"}>
                        {token.amount} {token.symbol}
                      </Text>
                      <CurrencyLogo currency={incentiveTokenObjects[index]} size={14} />
                    </Flex>
                  </MouseoverTooltip>)}
              </Flex>}

            {
    /* User gauge deposits */
  }
            {hasDeposits && <>
                {totalStaked > 0 && <MouseoverTooltip
    text={`You have ${totalStaked.toFixed(4)} tokens staked in gauge for this pool`}
    size={TooltipSize.Small}
  >
                    <Flex row alignItems="center" gap={"$gap4"}>
                      <TrendingUp size={12} color={colors.neutral2Temp.val} />
                      <Text variant="body4" color="$neutral2Temp" fontWeight="$medium" fontSize={"$micro"}>
                        {totalStaked.toFixed(2)} Staked
                      </Text>
                    </Flex>
                  </MouseoverTooltip>}
                {totalUnstaked > 0 && <MouseoverTooltip
    text={`You have ${totalUnstaked.toFixed(4)} tokens available to stake in gauge`}
    size={TooltipSize.Small}
  >
                    <Flex row alignItems="center" gap={"$gap4"}>
                      <DollarSign size={12} color={colors.neutral2.val} />
                      <Text variant="body4" color="$neutral2" fontSize={"$micro"}>
                        {totalUnstaked.toFixed(2)} Available
                      </Text>
                    </Flex>
                  </MouseoverTooltip>}
                {totalPendingRewards > 0 && <MouseoverTooltip
    text={`You have ${totalPendingRewards.toFixed(6)} ABX rewards pending from this pool's gauge`}
    size={TooltipSize.Small}
  >
                    <Flex row alignItems="center" gap={"$gap4"}>
                      <Text variant="body4" color="$accent2" fontSize={"$micro"}>
                        +{totalPendingRewards.toFixed(3)} ABX
                      </Text>
                    </Flex>
                  </MouseoverTooltip>}
              </>}
          </Flex>}
      </Flex>
    </Flex>;
}
