"use strict";
import { useAvailableGauges } from "hooks/useGaugeData";
import { useDexScreenerTokenData } from "hooks/useDexScreenerTokenData";
import { useGaugeAprBatch } from "hooks/useGaugeApr";
import { useMemo } from "react";
import { useChainId } from "wagmi";
import { Flex, Text } from "ui/src";
import { LP_INCENTIVES_REWARD_TOKEN } from "components/LpIncentives/constants";
import { useIncentivizeContext } from "../ContextProvider";
import SinglePool from "./SinglePool";
import SinglePoolLoader from "./SinglePoolLoader";
export default function StepOnePools() {
  const { data: gaugesData, isLoading: gaugesLoading } = useAvailableGauges();
  const { selectedPoolType, setSelectedPoolType, token0, setToken0, token1, setToken1 } = useIncentivizeContext();
  const chainId = useChainId();
  const { data: abxPriceData } = useDexScreenerTokenData(
    LP_INCENTIVES_REWARD_TOKEN.chainId,
    LP_INCENTIVES_REWARD_TOKEN.address
  );
  const abxPrice = useMemo(() => {
    if (!abxPriceData?.priceUsd) {
      return void 0;
    }
    const parsed = Number.parseFloat(abxPriceData.priceUsd);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : void 0;
  }, [abxPriceData?.priceUsd]);
  const incentivizablePools = useMemo(() => {
    if (!gaugesData) return [];
    let filteredPools = gaugesData.filter((gauge) => {
      return gauge.bribeContract && gauge.bribeContract !== "0x0000000000000000000000000000000000000000" && gauge.isAlive;
    });
    if (selectedPoolType !== -1) {
      filteredPools = filteredPools.filter((gauge) => {
        const isConcentrated = gauge.poolType === "V3" || gauge.poolType === "CL";
        const isBasic = gauge.poolType === "V2";
        if (selectedPoolType === 0) return isConcentrated;
        if (selectedPoolType === 1) return isBasic;
        return true;
      });
    }
    if (token0 || token1) {
      filteredPools = filteredPools.filter((gauge) => {
        if (token0 && token1) {
          const poolToken0Addr = gauge.token0?.address?.toLowerCase() || gauge.token0?.id?.toLowerCase();
          const poolToken1Addr = gauge.token1?.address?.toLowerCase() || gauge.token1?.id?.toLowerCase();
          const selectedToken0Addr = token0?.address?.toLowerCase() || token0?.id?.toLowerCase();
          const selectedToken1Addr = token1?.address?.toLowerCase() || token1?.id?.toLowerCase();
          const poolTokens = [poolToken0Addr, poolToken1Addr].filter(Boolean);
          const selectedTokens = [selectedToken0Addr, selectedToken1Addr].filter(Boolean);
          const hasToken0 = poolTokens.includes(selectedTokens[0]);
          const hasToken1 = poolTokens.includes(selectedTokens[1]);
          return hasToken0 && hasToken1;
        }
        if (token0 && !token1) {
          const poolToken0Addr = gauge.token0?.address?.toLowerCase() || gauge.token0?.id?.toLowerCase();
          const poolToken1Addr = gauge.token1?.address?.toLowerCase() || gauge.token1?.id?.toLowerCase();
          const selectedToken0Addr = token0?.address?.toLowerCase() || token0?.id?.toLowerCase();
          return poolToken0Addr === selectedToken0Addr || poolToken1Addr === selectedToken0Addr;
        }
        if (token1 && !token0) {
          const poolToken0Addr = gauge.token0?.address?.toLowerCase() || gauge.token0?.id?.toLowerCase();
          const poolToken1Addr = gauge.token1?.address?.toLowerCase() || gauge.token1?.id?.toLowerCase();
          const selectedToken1Addr = token1?.address?.toLowerCase() || token1?.id?.toLowerCase();
          return poolToken0Addr === selectedToken1Addr || poolToken1Addr === selectedToken1Addr;
        }
        return true;
      });
    }
    return filteredPools.map((gauge) => ({
      id: gauge.pool,
      token0: gauge.token0,
      token1: gauge.token1,
      reserveUSD: gauge.reserveUSD,
      volumeUSD: gauge.volumeUSD,
      totalValueLockedUSD: gauge.totalValueLockedUSD,
      totalValueLockedToken0: gauge.totalValueLockedToken0,
      totalValueLockedToken1: gauge.totalValueLockedToken1,
      protocol: gauge.poolType,
      // Now uses corrected poolType from useAvailableGauges
      type: gauge.poolType === "V2" ? "Volatile" : "Concentrated",
      // Add type field for V2 classification
      gauge
    }));
  }, [gaugesData, selectedPoolType, token0, token1]);
  const gaugeAprInputs = useMemo(() => {
    if (!abxPrice || !incentivizablePools.length) {
      return [];
    }
    return incentivizablePools.map((pool) => {
      const candidates = [pool.gauge?.totalValueLockedUSD, pool.totalValueLockedUSD, pool.reserveUSD];
      let tvl;
      for (const candidate of candidates) {
        if (candidate === void 0 || candidate === null) {
          continue;
        }
        const numeric = typeof candidate === "number" ? candidate : Number.parseFloat(typeof candidate === "string" ? candidate : String(candidate));
        if (Number.isFinite(numeric) && numeric > 0) {
          tvl = numeric;
          break;
        }
      }
      return {
        key: pool.id.toLowerCase(),
        gaugeAddress: pool.gauge?.id,
        poolAddress: pool.id,
        poolType: pool.protocol,
        tvlUSD: tvl,
        abxPriceUSD: abxPrice,
        chainId,
        poolMetadata: pool,
        enabled: Boolean(pool.gauge?.id && tvl && abxPrice)
      };
    });
  }, [abxPrice, chainId, incentivizablePools]);
  const gaugeAprMap = useGaugeAprBatch(gaugeAprInputs);
  if (gaugesLoading) {
    return <Flex gap={"$gap24"} mt={"$spacing24"}>
        {Array.from({ length: 3 }, (_, index) => <SinglePoolLoader key={index} />)}
      </Flex>;
  }
  if (!incentivizablePools.length) {
    return <Flex marginTop={"$spacing36"} mt={"$spacing24"} centered flexDirection="column" gap="$spacing16">
        <Text variant="body2" color="$neutral2">
          No pools available for incentivization
        </Text>
        <Text variant="body3" color="$neutral3" textAlign="center" maxWidth={400}>
          Only pools with active gauges and bribe contracts can be incentivized. Contact the protocol team if you need a
          gauge created for a specific pool.
        </Text>
      </Flex>;
  }
  const hasActiveFilters = selectedPoolType !== -1 || token0 || token1;
  return <Flex mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
      {hasActiveFilters && <Flex row justifyContent="space-between" alignItems="center">
          <Text variant="body2" color="$neutral2">
            {incentivizablePools.length} pool{incentivizablePools.length !== 1 ? "s" : ""} match
            {incentivizablePools.length === 1 ? "es" : ""} your filters
          </Text>
          <Text
    variant="body3"
    color="$neutral2Temp"
    cursor="pointer"
    onPress={() => {
      setSelectedPoolType(-1);
      setToken0("");
      setToken1("");
    }}
  >
            Clear filters
          </Text>
        </Flex>}
      {incentivizablePools.map((pool) => <SinglePool key={pool.id} pool={pool} gaugeApr={gaugeAprMap.get(pool.id.toLowerCase())} />)}
    </Flex>;
}
