"use strict";
import { CurrencyAmount, Token } from "@uniswap/sdk-core";
import CurrencySearchModal from "components/SearchModal/CurrencySearchModal";
import { useAccount } from "hooks/useAccount";
import useCurrencyBalance from "lib/hooks/useCurrencyBalance";
import { useUSDPrice } from "hooks/useUSDPrice";
import { useMemo, useRef, useState } from "react";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
import { useEnabledChains } from "uniswap/src/features/chains/hooks/useEnabledChains";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { parseUnits } from "viem";
import { useChainId } from "wagmi";
import { useIncentivizeContext } from "../ContextProvider";
import { CurrencySelector } from "./CurrencySelector";
const StyledInput = styled.input`
  text-align: right;
  padding: 12px 0;
  background-color: transparent;
  border: none;
  outline: none;
  font-size: 28px;
  @media (max-width: 768px) {
    font-size: 20px;
    padding: 8px 0;
  }
`;
export default function IncentivizeInput() {
  const inputRef = useRef(null);
  const { incentiveAmount, setIncentiveAmount, incentiveToken, setIncentiveToken, setHasValidBalance } = useIncentivizeContext();
  const [value, setValue] = useState("");
  const [isOpenCurrencyModal, setIsOpenCurrencyModal] = useState(false);
  const [selectedToken, setSelectedToken] = useState(null);
  const { chains } = useEnabledChains();
  const colors = useSporeColors();
  const { address } = useAccount();
  const { formatCurrencyAmount, formatNumber } = useFormatter();
  const chainId = useChainId();
  const currency = selectedToken ? new Token(
    chainId,
    selectedToken.address,
    selectedToken.decimals,
    selectedToken.symbol,
    selectedToken.name
  ) : void 0;
  const balance = useCurrencyBalance(address, currency);
  const fiatValue = useUSDPrice(incentiveAmount);
  const isAmountValid = useMemo(() => {
    if (!balance || !value || !selectedToken) {
      setHasValidBalance(true);
      return true;
    }
    try {
      const enteredAmount = parseFloat(value);
      const balanceAmount = parseFloat(balance.toExact());
      const isValid = enteredAmount <= balanceAmount && enteredAmount > 0;
      setHasValidBalance(isValid);
      return isValid;
    } catch (error) {
      setHasValidBalance(true);
      return true;
    }
  }, [balance, value, selectedToken, setHasValidBalance]);
  const handleMaxClick = () => {
    if (balance && selectedToken) {
      const maxAmount = balance.toExact();
      setValue(maxAmount);
      try {
        const token = new Token(
          chainId,
          selectedToken.address,
          selectedToken.decimals,
          selectedToken.symbol,
          selectedToken.name
        );
        setIncentiveAmount(balance);
        setIncentiveToken(token);
      } catch (error) {
        console.warn("Failed to set max amount:", error);
      }
    }
  };
  const handleChange = (text) => {
    const numericValue = text.replace(/[^0-9.]/g, "");
    setValue(numericValue);
    if (numericValue && selectedToken) {
      try {
        const token = new Token(
          chainId,
          selectedToken.address,
          selectedToken.decimals,
          selectedToken.symbol,
          selectedToken.name
        );
        const amount = CurrencyAmount.fromRawAmount(token, parseUnits(numericValue, selectedToken.decimals).toString());
        setIncentiveAmount(amount);
        setIncentiveToken(token);
      } catch (error) {
        console.warn("Failed to create currency amount:", error);
      }
    } else {
      setIncentiveAmount(void 0);
      setIncentiveToken(void 0);
    }
  };
  const handleCurrencySelect = (currency2) => {
    setIsOpenCurrencyModal(false);
    setSelectedToken(currency2);
    if (value && currency2) {
      try {
        const token = new Token(
          chainId,
          currency2.address,
          currency2.decimals,
          currency2.symbol,
          currency2.name
        );
        const amount = CurrencyAmount.fromRawAmount(token, parseUnits(value, currency2.decimals).toString());
        setIncentiveAmount(amount);
        setIncentiveToken(token);
      } catch (error) {
        console.warn("Failed to create currency amount:", error);
      }
    }
  };
  return <Flex mt={"$gap24"}>
      <Flex row alignItems="center" justifyContent="space-between" gap={"$gap12"}>
        <Text variant="body3" fontWeight={"$medium"}>
          Your incentive
        </Text>
        <Flex row alignItems="center" gap={"$gap8"}>
          <Text variant="body3" color={"$neutral2"}>
            Balance:
          </Text>
          <Text variant="body3" color={balance ? "$neutral1" : "$neutral3"}>
            {selectedToken && balance ? formatCurrencyAmount({ amount: balance, type: NumberType.TokenNonTx }) : selectedToken ? "0.00" : "--"}
            {selectedToken ? ` ${selectedToken.symbol}` : ""}
          </Text>
          {balance && selectedToken && parseFloat(balance.toExact()) > 0 && <Text
    variant="body4"
    color="$neutral2Temp"
    cursor="pointer"
    onPress={handleMaxClick}
    hoverStyle={{ color: "$accent1Hovered" }}
    style={{ textDecoration: "underline" }}
  >
              MAX
            </Text>}
        </Flex>
      </Flex>
      <Flex
    row
    mt={"$gap12"}
    px="$spacing16"
    py="$spacing16"
    borderWidth={1}
    borderColor={!isAmountValid ? "$red" : "$surface3"}
    justifyContent="space-between"
    alignItems="center"
    gap={"$gap12"}
    borderRadius={"$rounded12"}
    onPress={() => inputRef.current?.focus()}
    $platform-web={{
      focusWithinStyle: { borderColor: !isAmountValid ? "$red" : "$neutral2" }
    }}
    transition="border-color 0.3s ease"
    $lg={{
      px: "$spacing12",
      py: "$spacing8"
    }}
  >
        <Flex>
          <CurrencySelector
    emphasis={selectedToken ? void 0 : "secondary"}
    currencyInfo={selectedToken}
    onPress={() => setIsOpenCurrencyModal(true)}
  />
        </Flex>
        <Flex flexDirection="column" gap={"$gap8"} flex={1}>
          <StyledInput
    ref={inputRef}
    onChange={(e) => handleChange(e.target.value)}
    type="text"
    value={value}
    style={{ color: colors.neutral1.val }}
  />

          {!isAmountValid && value && selectedToken ? <Text variant="body4" color={"$red"} textAlign="right">
              Insufficient balance
            </Text> : <Text variant="body3" color={"$neutral3"} textAlign="right">
              {fiatValue.data ? formatNumber({
    input: fiatValue.data,
    type: NumberType.FiatTokenPrice
  }) : "~$0"}
            </Text>}
        </Flex>
        <CurrencySearchModal
    isOpen={isOpenCurrencyModal}
    onDismiss={() => setIsOpenCurrencyModal(false)}
    onCurrencySelect={handleCurrencySelect}
    chainIds={chains}
    excludeNativeTokens={true}
    whitelistedTokensOnly={true}
  />
      </Flex>
    </Flex>;
}
